SELECT R.[ID], R.[MODULE_NAME], R.[REVISION], R.[SOURCE], R.[CREATED_DATE], P.[KEY] AS PROJECT_KEY 
FROM [PROJECT_MODULE_REVISIONS] R 
	INNER JOIN [PROJECTS] P 
			ON R.[PROJECT_ID] = P.[ID] 
WHERE R.[IsDeleted] = 0 
	AND P.[KEY] = @PRM_PROJECTS_KEY 
	AND P.[IS_ACTIVE] = 1 
ORDER BY R.[CREATED_DATE] DESC 